fn fibonacci(n: usize) -> Vec<i32> {
    // Problem guarantees n >= 2.
    let mut ret = vec![0i32; n];
    ret[0] = 0;
    ret[1] = 1;

    for i in 2..n {
        let a = ret[i - 1] as i64;
        let b = ret[i - 2] as i64;
        ret[i] = (a + b) as i32; // Safe under the guarantee that outputs fit in i32.
    }

    ret
}